      for (let i = 0; i < 3; i++) { const x = 990 + i * 120; s += `<path d="M${x} 1470 v90 m-38 -38 l38 38 l38 -38" stroke="${i === 2 ? A : I}" stroke-width="16" fill="none" stroke-linecap="round" stroke-linejoin="round" opacity="${i === 2 ? 1 : 0.4}"/>`; }
